statement:
You get a binary matrix `mat` with `m` rows and `n` columns. A line is a run of neighbouring cells that all hold `1` and follow one of four directions:

- horizontal (along a row);
- vertical (along a column);
- diagonal (each step goes one row down and one column right);
- anti-diagonal (each step goes one row down and one column left).

Return the number of cells in the longest such line. A single `1` is a line of length 1, and a matrix without any `1` gives `0`.

validator:
function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1) return 'mat needs at least one row.';
  const n = mat[0].length;
  if (n < 1) return 'Each row needs at least one cell.';
  if (mat.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (mat.length * n > 10000) return 'mat can hold at most 10^4 cells.';
  if (mat.some(row => row.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 or 1.';
  return null;
}

reference:
function longestLine(mat) {
  const rows = mat.length;
  const cols = mat[0].length;
  const dp = Array.from({ length: rows }, () => Array.from({ length: cols }, () => [0, 0, 0, 0]));
  let best = 0;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (mat[r][c] === 0) {
        continue;
      }
      const cell = dp[r][c];
      cell[0] = c > 0 ? dp[r][c - 1][0] + 1 : 1;
      cell[1] = r > 0 ? dp[r - 1][c][1] + 1 : 1;
      cell[2] = r > 0 && c > 0 ? dp[r - 1][c - 1][2] + 1 : 1;
      cell[3] = r > 0 && c + 1 < cols ? dp[r - 1][c + 1][3] + 1 : 1;
      best = Math.max(best, cell[0], cell[1], cell[2], cell[3]);
    }
  }
  return best;
}

brute:
function longestLine(mat) {
  const m = mat.length;
  const n = mat[0].length;
  const steps = [[0, 1], [1, 0], [1, 1], [1, -1]];
  let answer = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      for (const [di, dj] of steps) {
        let length = 0;
        let x = i;
        let y = j;
        while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] === 1) {
          length++;
          x += di;
          y += dj;
        }
        answer = Math.max(answer, length);
      }
    }
  }
  return answer;
}

generator:
function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const roll = rand();
  const density = roll < 0.1 ? 0 : roll < 0.2 ? 1 : size === 'large' ? 0.7 + rand() * 0.25 : rand();
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  return [mat];
}
